import path from 'path';

// A Flutter app for Android, always the "frontend" half of a fullstack project (mobile/ next to backend/).
// Generated by `flutter create`; Shipyard then wires it to the backend (fullstack.js) and the lane builds
// and tests it, and QCs the APK on the shared Android emulator.

/** "ban-hang" → "ban_hang" (a Dart package name: lower case, digits and _ , starting with a letter). */
export const dartName = slug => {
  const n = String(slug).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  return /^[a-z]/.test(n) ? n : `app_${n}`;
};

export default {
  id: 'flutter-android',
  language: 'dart', languageLabel: 'Dart',
  label: 'Flutter (Android)', description: 'App Android viết bằng Flutter, gọi API của backend trong cùng dự án',
  appPort: null,
  noDatabase: true,
  options: [
    { id: 'tests', label: 'Kiểm thử bằng flutter test', type: 'bool', default: true },
    { id: 'org', label: 'Tên tổ chức (package id)', type: 'text', default: 'com.example',
      pattern: '^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)+$', help: 'Dạng tên miền ngược, ví dụ com.congty — app có id <tên tổ chức>.<tên dự án>' },
  ],
  requires: () => ['flutter', 'git'],
  check: () => '',

  async generate(ctx) {
    await ctx.run('flutter', ['create', '--org', ctx.options.org, '--platforms', 'android', '--project-name', dartName(ctx.slug),
      path.basename(ctx.dir)], { cwd: ctx.parentDir });
  },

  // After Shipyard's wiring (fullstack.js): the app must resolve, pass the analyzer and its tests.
  async verify(ctx) {
    await ctx.run('flutter', ['pub', 'get'], { cwd: ctx.dir });
    await ctx.run('flutter', ['analyze'], { cwd: ctx.dir });
    if (ctx.options.tests !== false) await ctx.run('flutter', ['test'], { cwd: ctx.dir });
  },

  overlay: () => ({}),
  env: () => ({}),
  commands: () => ({ install: 'flutter pub get', dev: 'flutter run', build: 'flutter build apk --debug', test: 'flutter test' }),
  gitignore: () => '.dart_tool/\n.flutter-plugins\n.flutter-plugins-dependencies\nbuild/\n*.iml\n.idea/\nandroid/local.properties\n',
};
